import{a as J}from"./chunk-KX6BR77K.js";import{a as Z,b as X,c as Q}from"./chunk-UURGSE3Y.js";import{a as L,c as K}from"./chunk-K2LUQJUN.js";import{a as H}from"./chunk-7WKP3FQK.js";import"./chunk-EC7AOHMG.js";import{a as Y}from"./chunk-YCQPJTQL.js";import{d as V,n as N,p as W}from"./chunk-MNQC3QBW.js";import{$ as M,$b as D,Ab as F,Eb as C,Fb as I,Jb as P,Lb as m,Na as A,Qa as r,Vb as b,W as S,Xb as _,Zb as o,_b as l,aa as O,db as U,gc as $,hc as T,ib as w,ic as z,jc as G,lc as q,o as R,pc as B,qb as k,rb as y,sb as v,tb as E,ub as x,vb as c,wb as d,xb as h,yb as n,zb as t}from"./chunk-PAGRJQTH.js";var ee={title:"Waffic",eyebrow:"Bachelor's thesis \xB7 Economic Informatics \xB7 2018",slogan:"Weather and traffic for the road ahead, on one screen.",tagline:"Vue.js \xB7 Firebase \xB7 Google Maps \xB7 AccuWeather",links:[{label:"Live demo",url:"https://waffic1997.web.app/"},{label:"Source code",url:"https://github.com/madalinaeleonorag/Waffic"}],hero:{image:"waffic/map.webp",alt:"Waffic map: a driving route from Bucharest to Bra\u0219ov, with the weather at the start and at the destination in the top bar",caption:"The route and the weather at both ends of the trip"},techStack:["Vue 2","Vuex","Vue Router","Vuetify","Firebase","Google Maps API","AccuWeather API","Google Charts"],summary:["Waffic (weather + traffic) is the web application I built for my bachelor\u2019s thesis in Economic Informatics at the Romanian-American University. Before a drive, a user picks a destination and sees the driving route on a map, with the current weather at the start and at the destination. Every search is kept as a travel history.","It also has a business side. Companies can buy a collaboration plan that puts their location on the map and alerts drivers who pass nearby. Administrators answer contact messages and follow usage through statistics and reports."],idea:{intro:"Bring traffic and weather information into one interface, so drivers can avoid delays caused by not knowing the weather at their destination.",points:["The weather where you start says little about the weather where you arrive, hours later.","Checking a navigation app and a weather app in turn, during the trip, is slow and distracting.","Local businesses along a route had no simple way to reach drivers passing by."]},roles:[{title:"Visitor",text:"Anyone who opens the site.",can:["See the collaboration plans","Read the tutorial","Send a contact message","Create an account"]},{title:"Driver",text:"A signed-in user.",can:["Plan a trip with route and weather","Keep, star and delete past trips","Edit personal details","Buy a collaboration plan for a business"]},{title:"Administrator",text:"A user marked as admin in the database.",can:["Answer and archive contact messages","Follow statistics and reports","Search users, collaborations and destinations"]}],featureGroups:[{title:"Route and weather on one screen",text:"Type a destination in the top bar. The map draws the driving route from where you are, and the top bar shows the weather at both ends.",shots:[{image:"waffic/map.webp",alt:"Map with a driving route from Bucharest to Bra\u0219ov, company pins, and weather for both cities",caption:"Route, pins and weather"}],features:[{title:"Destination search",text:"Google Places autocomplete in the top bar."},{title:"Driving route from your location",text:"The browser\u2019s location is the start; Google Directions draws the route."},{title:"Weather at both ends",text:"Current conditions from AccuWeather, with an icon and temperature for the start and the destination."},{title:"Kept up to date",text:"Route and weather refresh every 10 minutes while the map is open."}]},{title:"Travel history",text:"Every trip searched is saved, so frequent routes are one tap away.",shots:[{image:"waffic/travel-history.webp",alt:"Travel history table with start, destination, date, delete and favourite star for each trip",caption:"Travel history with favourites"}],features:[{title:"Saved automatically",text:"Start city, destination and date for each search."},{title:"Favourites",text:"Star the trips you repeat; delete the ones you do not need."}]},{title:"Collaborations for businesses",text:"Companies buy a plan and appear on every driver\u2019s map.",shots:[{image:"waffic/collaborations.webp",alt:"Five collaboration plans from 7 days for 5 RON to 365 days for 75 RON, with a warning that a new plan replaces the active one",caption:"Collaboration plans"}],features:[{title:"Five plans",text:"From 7 days for 5 RON to a year for 75 RON. A new plan replaces the active one, and the page says so before you buy."},{title:"Company pins",text:"Each active company is a marker on the map, with its name on click."},{title:"Nearby alert",text:"When a driver is within about 500 m of a company, Waffic shows its name and description."}]},{title:"Administration",text:"A separate menu section for administrators, visible only to them.",shots:[{image:"waffic/admin-account.webp",alt:"Side menu with Administration: messages, statistics and reports, search",caption:"Admin menu"},{image:"waffic/statistics.webp",alt:"Statistics: pie charts for users with and without collaborations and history, top localities, plans and ages, an age histogram and all searched destinations",caption:"Statistics and reports"}],features:[{title:"Messages",text:"Contact messages in a table; mark as answered or delete."},{title:"Statistics and reports",text:"Users with and without collaborations or trips, age distribution, top localities, plans and destinations, drawn with Google Charts."},{title:"Search",text:"Find users by name, collaborations by date range, and how often each destination was searched."}]},{title:"Accounts and consent",text:"Email and password accounts, with the essentials around them.",shots:[{image:"waffic/signup.webp",alt:"Sign-up dialog: email, name, surname, locality, birth date, password and confirmation",caption:"Sign-up"}],features:[{title:"Sign-up and password reset",text:"Firebase Authentication, with a reset email for forgotten passwords."},{title:"GDPR consent",text:"A consent dialog after sign-in until the user accepts."},{title:"Tutorial",text:"A help page that explains every screen, in Romanian like the rest of the interface."}]}],gallery:[{image:"waffic/homepage.webp",alt:"Home page with the Waffic logo and buttons to sign in or create an account",caption:"Home"},{image:"waffic/signup.webp",alt:"Sign-up dialog",caption:"Sign-up"},{image:"waffic/map.webp",alt:"Map with route and weather",caption:"Map"},{image:"waffic/travel-history.webp",alt:"Travel history",caption:"Travel history"},{image:"waffic/collaborations.webp",alt:"Collaboration plans",caption:"Collaborations"},{image:"waffic/admin-account.webp",alt:"Administrator menu",caption:"Admin menu"},{image:"waffic/statistics.webp",alt:"Statistics charts",caption:"Statistics"},{image:"waffic/tutorial.webp",alt:"Tutorial page in Romanian",caption:"Tutorial"}],architectureIntro:"A single-page application with no server code of its own. Vue components talk directly to Firebase (Authentication and the Realtime Database) and call Google Maps and AccuWeather from the browser. The production build is made with webpack, includes a web app manifest and a service worker, and is served from Firebase Hosting.",diagram:{label:"Container diagram: a Vue single-page app on Firebase, calling map and weather APIs from the browser",actors:[{title:"Driver",text:"Plans trips, keeps a history"},{title:"Business",text:"Buys a plan to appear on the map"},{title:"Administrator",text:"Messages, statistics, search"}],client:{label:"Browser \xB7 Vue 2 single-page app",boxes:[{title:"Vuetify views + Vue Router",text:"12 routes; a guard sends signed-out users home."},{title:"Vuex store",text:"User, role, location, destination and weather. Firebase listeners commit here."}]},backend:{label:"Firebase",boxes:[{title:"Realtime Database",text:"Users, trips, collaborations, plans, messages"},{title:"Authentication \xB7 Hosting",text:"Email and password; the static build"}]},external:[{title:"Google Maps JavaScript API",text:"Map, Directions, Geocoder, Places"},{title:"AccuWeather API",text:"Location key, then current conditions"},{title:"Google Charts",text:"Admin statistics"}]},layers:[{name:"Views",text:"One Vuetify component per screen: map, history, collaborations, statistics, search, messages."},{name:"Routing",text:"Vue Router with an auth guard on every page that needs an account."},{name:"State",text:"Vuex. Actions open real-time Firebase listeners and commit mutations; getters feed the views, so the map, top bar and history stay in sync.",highlight:!0},{name:"Data",text:"Firebase Realtime Database paths, read with live \u201Cvalue\u201D listeners and written with set, push and update."},{name:"Integrations",text:"Google Maps, AccuWeather (XMLHttpRequest) and Google Charts, loaded in the browser."}],dataModel:{intro:"The Realtime Database is one JSON tree. Each user\u2019s data sits under their Firebase user id, so a listener on one path follows exactly one user.",rows:[{name:"UserDetails/{uid}",holds:"Name, locality, birth date, email, phone, admin flag, GDPR consent, plans bought"},{name:"userDestinationsHistory/{uid}/{id}",holds:"Start, destination, date, favourite"},{name:"Collaborations/{uid}",holds:"Company name, description, coordinates, start date, plan. One active plan per account."},{name:"TypesOfCollaborations",holds:"Plan name, duration in days, price, description"},{name:"ContactMessages",holds:"Email, name, message, answered flag"}],image:{image:"waffic/database.webp",alt:"Firebase console tree: Collaborations, ContactMessages, TypesOfCollaborations, TypesOfPayment, UserDetails, userDestinationsHistory",caption:"The database tree in the Firebase console"}},flows:[{title:"Planning a trip",steps:["On sign-in, the store opens live listeners on the user\u2019s profile, role and consent.","The browser\u2019s location becomes the start point.","The user picks a destination in the autocomplete; the store keeps it.","The map watches the destination and asks Google Directions for a driving route.","For each end, AccuWeather is called twice: once for a location key, then for current conditions. Icon and temperature go to the store and the top bar.","The trip is saved to the user\u2019s history, and route and weather refresh every 10 minutes."]},{title:"Company pins and nearby alerts",steps:["A business buys a plan; its details and coordinates are written to Collaborations, replacing any active plan.","The map listens to Collaborations and draws one marker per company.","For each company, the app estimates the distance from the driver. Under about 500 m it shows the company\u2019s name and description."]}],codeSample:{title:"Live data through the store",intro:"Every list in Waffic follows the same pattern: a Vuex action opens a Firebase listener once, and mutations keep the state in step with the database, including deletions made in another tab. Simplified:",code:`// Vuex action: keeps the trip history in sync with the database
getData({ commit }) {
  return firebase.database()
    .ref('userDestinationsHistory/' + this.state.user.uid)
    .on('value', snap => {
      const trips = snap.val() || {};
      const keys = Object.keys(trips);
      keys.forEach(key => commit('gotuserHistory', { key, ...trips[key] }));
      commit('getKeys', keys); // drops trips deleted elsewhere
    });
}`},lookingBack:[{then:"API keys for Google Maps and AccuWeather are in the client code and the repository.",today:"Keys restricted by domain, and weather calls through a small server function that also caches results."},{then:"The route guard only checks that someone is signed in. Admin pages are hidden in the menu, not protected.",today:"Roles as Firebase custom claims, checked by route guards and enforced by database security rules."},{then:"Weather is fetched over plain HTTP with nested XMLHttpRequests, and a 3-second timer waits for both answers.",today:"HTTPS calls with fetch and async/await, waiting on both ends with Promise.all."},{then:"Distance to a company is a straight-line formula on latitude and longitude, which distorts with direction.",today:"The Maps geometry library (or the haversine formula) for real distances in metres."},{then:"Statistics are computed in the browser by downloading every user and every trip.",today:"Totals kept up to date by server functions, so the dashboard reads a few small documents."},{then:"Plain JavaScript and no automated tests.",today:"TypeScript, and unit tests for the store and the trip flow."}],thesis:{title:"Waffic: an integrated application for following traffic and weather conditions",sections:[{heading:"About the thesis",paragraphs:["Bachelor\u2019s thesis at the Faculty of Managerial Informatics, Romanian-American University, Bucharest, class of 2018. Supervisor: Alexandru T\u0103bu\u0219c\u0103.","Purpose: bring traffic and weather information into a single interface. Use: avoid delays caused by missing weather information at the destination, and by switching between specialised apps during the trip."]},{heading:"Research and analysis",paragraphs:["The thesis starts with a short history of the field and a review of the apps drivers already used. It maps the information flow of the existing system and the ways it could be improved, and includes a survey asking potential users how useful such an app would be."]},{heading:"Design",paragraphs:["The overall design defines the application\u2019s objectives, the reports it produces, the coding system, the data and processing models and the entity-relationship diagram. It also covers the choice of technology and a plan of resources and schedule.","The detailed design covers the logical and physical design of inputs and outputs, the database, the system diagram and the interface."]},{heading:"Monetising web applications",paragraphs:["A separate chapter compares freemium and premium business models across app categories, from navigation and productivity to games and social networks. In the app, revenue comes from paid collaboration plans for businesses, while drivers use it for free."]},{heading:"Conclusions",paragraphs:["Waffic shortens the time drivers spend checking information and helps them avoid delays in traffic or at the destination caused by the weather. It is easy to use for anyone who wants real-time information for a safer trip."]}]}};var te={title:"UniversityRating",eyebrow:"Master's thesis \xB7 Economic Informatics \xB7 2020",slogan:"Compare Romanian universities and study programmes, with reviews checked by AI before they go live.",tagline:"Angular \xB7 Firestore \xB7 Azure Text Analytics \xB7 Google Maps",links:[{label:"Live demo",url:"https://universityraking.web.app/"},{label:"Source code",url:"https://github.com/madalinaeleonorag/UniversityRating"}],hero:{image:"university-rating/search.webp",alt:"UniView search: filters for study level, name, description, location, facilities, rating and institution type, above cards for seven universities",caption:"Search with filters, ratings and favourites"},techStack:["Angular 8","TypeScript","RxJS","Angular Material","Cloud Firestore","Azure Text Analytics","Google Maps API","Google Charts"],summary:["UniversityRating, published as UniView, is the web application I built for my master\u2019s thesis in Economic Informatics at the Romanian-American University. Future students search universities, faculties and bachelor\u2019s, master\u2019s and doctoral programmes, and see each one\u2019s courses, facilities, location and reviews.","Content comes from two sides. Universities manage their own pages through representative accounts that an administrator verifies. Students leave star ratings and comments, and every comment goes through sentiment analysis in Azure Text Analytics: neutral and positive comments are published at once, negative ones wait for an administrator."],idea:{intro:"Bring information about universities into one place, kept up to date by a representative of each institution, with reviews filtered so they do not mislead future students.",points:["Future students had to search each university\u2019s website without guidance, and those websites gave no authorised person a way to keep information current.","Opinions about universities lived on social networks and forums, with no control, which created confusion.","Of the three similar platforms compared (UniApply, Optiuni.ro and Study in Romania), none let students write reviews or give ratings."]},roles:[{title:"Student",text:"Anyone looking for a university; an account is needed to review.",can:["Search and filter at every study level","Save favourites","Rate and comment on universities and faculties"]},{title:"University representative",text:"A student account upgraded after an administrator approves a request.",can:["Ask to add or claim a university","Edit the university page in place","Add faculties, programmes and courses"]},{title:"Administrator",text:"Keeps the content trustworthy.",can:["Approve or decline representative requests, with a reason","Approve or decline flagged reviews","Follow statistics and reports"]}],featureGroups:[{title:"Search and compare",text:"One search for every level of study, with the filters a future student actually uses.",shots:[{image:"university-rating/search.webp",alt:"Search results: seven university cards with ratings, review counts and favourite hearts",caption:"Search and filters"},{image:"university-rating/university.webp",alt:"University page: description, faculties, vision, values, strategic programmes, facilities, contact with map, and reviews",caption:"University page"}],features:[{title:"Five levels",text:"Universities, faculties, and bachelor\u2019s, master\u2019s and doctoral programmes."},{title:"Filters",text:"Name, description, location, facilities and public or private, sorted by rating."},{title:"Favourites",text:"A heart on every card, kept per level on the student\u2019s profile."},{title:"University pages",text:"Mission, vision, values, strategic programmes, 15 kinds of facilities, contact details and a map."}]},{title:"Faculties, programmes and courses",text:"The detail a student needs to choose a programme, not only a university.",shots:[{image:"university-rating/faculty.webp",alt:"Faculty page with tabs for bachelor\u2019s, master\u2019s and doctoral programmes; a programme shows years, semesters, skills, careers and courses",caption:"Faculty and programmes"},{image:"university-rating/course.webp",alt:"Course details: credits, evaluation, hours, semester and objectives",caption:"Course details"}],features:[{title:"Programmes by level",text:"Bachelor\u2019s, master\u2019s and doctoral tabs on each faculty page."},{title:"Programme details",text:"Years, semesters, general skills, career paths and the list of courses."},{title:"Course details",text:"Credits, evaluation, hours, semester and objectives."}]},{title:"Reviews with AI moderation",text:"Students rate and comment; a sentiment check decides what goes live at once.",shots:[],features:[{title:"Stars and comments",text:"For universities and faculties."},{title:"Sentiment check",text:"Each comment is analysed by Azure Text Analytics before it is saved."},{title:"Negative comments wait",text:"They are held for an administrator, and the author sees a note that the review is being checked."},{title:"Declined reviews do not count",text:"They are hidden and left out of the rating."}]},{title:"Verified university accounts",text:"Universities keep their own pages up to date, after an administrator checks who is asking.",shots:[{image:"university-rating/user-details.webp",alt:"Profile page showing an approved request and a button to view and edit the university",caption:"Approved request on the profile"},{image:"university-rating/university-edit.webp",alt:"University page in edit mode: type, name, website, description, faculties table, vision, values, facilities and contact",caption:"Editing a university in place"}],features:[{title:"Request",text:"Name, type, description, contact, location, facilities, logo and photos."},{title:"Approval",text:"The administrator approves, which creates the university page and links it to the account, or declines with a reason the user sees."},{title:"Edit in place",text:"Representatives edit the same pages students see, section by section."}]},{title:"Administration and reports",text:"An overview of users and content, and queues for what needs a decision.",shots:[{image:"university-rating/piecharts.webp",alt:"Dashboard of pie charts: education level, university types, users by sex, consent, request statuses, faculties, photos and programmes per university",caption:"Statistics"},{image:"university-rating/raports.webp",alt:"Reports table of bachelor\u2019s programmes with courses, years, semesters, skills and faculty",caption:"Reports"}],features:[{title:"Statistics",text:"About twenty charts on users, institutions, programmes, facilities and requests."},{title:"Reports",text:"Tables for universities, faculties, programmes and users."},{title:"Queues",text:"Representative requests and flagged reviews, each split into pending, approved and declined."}]},{title:"Others",text:"",shots:[],features:[{title:"Romanian and English",text:"Interface text through translation files."},{title:"Legal pages and consent",text:"Terms, privacy policy, copyright and GDPR consent on the profile."},{title:"Directions",text:"A route on the map from the student to the university."}]}],gallery:[{image:"university-rating/homepage.webp",alt:"Home page: Discover the universities in Romania, with search, review and claim explained",caption:"Home"},{image:"university-rating/search.webp",alt:"Search results",caption:"Search"},{image:"university-rating/university.webp",alt:"University page",caption:"University"},{image:"university-rating/faculty.webp",alt:"Faculty page",caption:"Faculty"},{image:"university-rating/course.webp",alt:"Course details",caption:"Course"},{image:"university-rating/user-details.webp",alt:"Profile with request status",caption:"Profile"},{image:"university-rating/university-edit.webp",alt:"University in edit mode",caption:"Edit mode"},{image:"university-rating/requests.webp",alt:"A pending representative request with approve and decline buttons",caption:"Requests queue"},{image:"university-rating/piecharts.webp",alt:"Pie chart statistics",caption:"Statistics"},{image:"university-rating/barcharts.webp",alt:"Bar chart statistics: user ages, facilities usage, class and school levels, locations",caption:"More statistics"},{image:"university-rating/raports.webp",alt:"Reports table",caption:"Reports"}],architectureIntro:"An Angular single-page application on Firebase, with no server code of its own. Pages read and write Cloud Firestore through AngularFire, sign users in with Firebase Authentication, store logos and photos in Firebase Storage, and call Azure Text Analytics and Google Maps from the browser.",diagram:{label:"Container diagram: an Angular single-page app on Firebase, with Azure AI for review moderation",actors:[{title:"Student",text:"Searches, saves, reviews"},{title:"Representative",text:"Edits a verified university"},{title:"Administrator",text:"Approves requests and reviews"}],client:{label:"Browser \xB7 Angular 8 single-page app",boxes:[{title:"Pages + Material components",text:"13 routes; 20 shared components, most of them switching between view and edit mode."},{title:"Services (RxJS)",text:"Data, auth, dashboard and text analysis services returning Observables."}]},backend:{label:"Firebase",boxes:[{title:"Cloud Firestore",text:"Universities, faculties, programmes, courses, reviews, requests, users"},{title:"Auth \xB7 Storage \xB7 Hosting",text:"Accounts; logos and photos; the static build"}]},external:[{title:"Azure Text Analytics",text:"Sentiment of each review comment"},{title:"Google Maps API",text:"Maps, places, geocoding, directions"},{title:"Google Charts",text:"Admin statistics"}]},layers:[{name:"Pages",text:"Search, university and faculty details, favourites, profile, requests, review queue, dashboard, legal pages."},{name:"Components",text:"Reusable \u201Ceditable\u201D blocks (lists, chips, facilities, star rating, comments) that show content to students and edit it for representatives."},{name:"Services",text:"All data access and outside calls. Pages subscribe to Firestore collections as Observables, so changes from another user appear without a reload.",highlight:!0},{name:"Models",text:"Typed classes for every document (University, Faculty, Review, Request, User), with safe defaults for missing fields."},{name:"Integrations",text:"AngularFire, the Azure Text Analytics SDK, Google Maps (AGM) and Google Charts."}],dataModel:{intro:"Firestore collections follow the hierarchy a student browses: university, faculty, programme, course. Reviews and requests point to them by id.",rows:[{name:"University",holds:"Name, type, description, mission, vision, values, strategic programmes, facilities, contact, location, logo, photos, rating"},{name:"Faculties",holds:"Name, description, location, logo, study guide, university id, ids of its programmes"},{name:"Bachelors \xB7 Masters \xB7 Doctorals",holds:"Name, years, semesters, general skills, career paths, courses, faculty id"},{name:"Courses",holds:"Name, credits, evaluation, hours, semester, objectives, study level"},{name:"Reviews",holds:"Stars, comment, date, status (approved, pending, declined), author, university or faculty id"},{name:"Requests",holds:"University details from the representative, status, administrator\u2019s answer, author"},{name:"Users",holds:"Profile, role, consent, favourites per level, request and university ids"}],image:{image:"university-rating/database.webp",alt:"Entity-relationship diagram in Romanian: user, request, university, review, faculty, bachelor\u2019s, master\u2019s and doctoral programmes, course",caption:"Entity-relationship diagram from the thesis"}},flows:[{title:"Publishing a review",steps:["A signed-in student picks a number of stars and writes a comment.","The comment is sent to Azure Text Analytics for sentiment analysis.","Positive, neutral or mixed: the review is saved as approved and appears at once.","Negative: it is saved as pending and the student sees that an administrator will check it.","The administrator approves or declines it in the review queue. Declined reviews are hidden and left out of the rating."]},{title:"Becoming a university representative",steps:["A student account sends a request with the university\u2019s details, logo, photos, facilities and location. It is saved as pending and linked to the profile.","An administrator reviews it in the requests queue.","Approve: the university page is created from the request, and the account is linked to it and becomes a representative.","Decline: the request is closed with a reason, shown on the user\u2019s profile.","The representative then edits the page and adds faculties, programmes and courses."]}],codeSample:{title:"Moderation in a few lines",intro:"The decision is a single rule on the sentiment label Azure returns. Everything that is not clearly negative is trusted; the rest waits for a person.",code:`addComment() {
  this.review.comment = this.commentText;
  this.azureService.sentimentAnalysis(this.review.comment).then((res) => {
    const data = new TextAnalyticData(res[0]);
    if (data.sentiment !== 'negative') {
      this.review.status = 'approved';
    } else {
      this.review.status = 'pending';
      this.negativeSentimentWarning = true;
    }
    this.firebaseService.addComment(this.review);
  });
}`},lookingBack:[{then:"Firestore security rules allow anyone to read and write every document.",today:"Rules per collection: only the author creates a review, only an administrator changes its status, only the linked representative edits a university."},{then:"The sentiment check runs in the browser, with the Azure key in the client bundle, so a modified client could mark its own review as approved.",today:"A server function triggered by each new review calls Azure and sets the status, with the key kept on the server."},{then:"Roles are checked only in the interface: admin links are hidden, but the routes are open.",today:"Roles as Firebase custom claims, enforced by route guards and security rules."},{then:"Statistics load whole collections into the browser.",today:"Counters kept up to date by server functions, read as a few small documents."},{then:"One data service of about 800 lines serves every page, and the generated tests were never filled in.",today:"A service per feature, and tests for the moderation and approval flows first."}],thesis:{title:"University Rating: an application for listing information about universities and reviewing them",sections:[{heading:"About the dissertation",paragraphs:["Master\u2019s dissertation at the Faculty of Managerial Informatics, Romanian-American University, Bucharest, 2020. Supervisor: Alexandru T\u0103bu\u0219c\u0103.","It analyses the existing systems and what users need, then designs and builds the application: finding the gaps in existing apps, defining inputs and outputs, choosing the technology, planning the work, choosing a way to monetise, and assessing how useful and efficient the result is."]},{heading:"Existing platforms",paragraphs:["Three similar platforms were compared. UniApply lets students apply to programmes across Europe but gives only short information about institutions. Optiuni.ro filters universities and compares programmes, in Romanian and English, and links to online admission. Study in Romania presents the Romanian universities\u2019 offer.","None of them let students write reviews or give ratings, and UniApply and Optiuni.ro gave universities no way to manage their own information. Those two gaps define UniversityRating."]},{heading:"Technology choices",paragraphs:["A web application, because most people look things up on their phone and a web app works on phones and computers regardless of the operating system.","Angular 8 for a single-page application, and Cloud Firestore as a document database: JSON-like collections with less denormalisation, offline support on the device, and real-time updates. Firebase hosting for fast delivery of a graphics-heavy app, reliability and SSL."]},{heading:"Data, reports and interface",paragraphs:["Nine entities (users, universities, faculties, bachelor\u2019s, master\u2019s and doctoral programmes, courses, requests and reviews), each specified field by field, with an entity-relationship diagram.","Fourteen reports, from the lists of universities, faculties and programmes to statistics on users\u2019 ages and education, facility usage and university locations.","The interface uses shades of classic blue, named colour of the year at the time, in a modern style aimed at young users, with the main colour easy to replace later."]},{heading:"Planning and monetisation",paragraphs:["The plan estimates a team of a project manager, a senior database developer, a senior web developer and a junior web developer: about 1,100 hours and roughly 52,800 lei.","The monetisation chapter finds that in-app advertising was still the largest source of app revenue, and compares its forms: banners, interstitials, native ads, partnerships between apps and rewarded ads."]},{heading:"Conclusions",paragraphs:["The application shortens the time needed to find accurate, current information about universities and helps future students choose a university or programme. It needs only a browser and an internet connection, and no special training."]}]}};va